// Sentientia LMS Real-time Leaderboard — client — Phase L.0.
//
// Opens EventSource(stream.php?boardid) and on 'leaderboard.recomputed'
// re-fetches the top-N via WS local_sentientia_leaderboard_get_board.
// Falls back to 30 s short-polling when SSE is disabled or unsupported.
//
// Built with named-define ES5 for the bundled context (see the
// AMD pipeline triple-bug fix note 2026-05-20 in PROJECT-STATE).
define('local_sentientia_leaderboard/leaderboard_client',
       ['core/ajax', 'core/str', 'core/notification'],
       function(Ajax, Str, Notification) {
    'use strict';

    var POLL_INTERVAL_MS = 30000;
    var SSE_RECONNECT_DELAY_MS = 5000;

    function fetchBoard(boardid) {
        return Ajax.call([{
            methodname: 'local_sentientia_leaderboard_get_board',
            args: {boardid: boardid, topn: 25}
        }])[0];
    }

    function renderRows(root, response) {
        var tbody = root.querySelector('[data-rows-body]');
        var table = root.querySelector('[data-rows-table]');

        if (!response.rows || response.rows.length === 0) {
            if (table) {
                var empty = document.createElement('div');
                empty.className = 'airpay-lb__empty';
                empty.setAttribute('data-empty-state', '');
                Str.get_string('no_entries',
                    'local_sentientia_leaderboard').then(function(s) {
                    empty.textContent = s;
                });
                table.parentNode.replaceChild(empty, table);
            }
            return;
        }

        if (!tbody) {
            return;
        }

        // Clear + rebuild rows.
        while (tbody.firstChild) {
            tbody.removeChild(tbody.firstChild);
        }
        response.rows.forEach(function(r) {
            var tr = document.createElement('tr');
            tr.className = 'airpay-lb__row';
            tr.setAttribute('data-userid', r.userid);

            var tdRank = document.createElement('td');
            tdRank.className = 'airpay-lb__rank';
            tdRank.textContent = r.rank;

            var tdUser = document.createElement('td');
            tdUser.className = 'airpay-lb__user';
            // textContent guards against XSS even though the server
            // format_string'd the name.
            tdUser.textContent = r.fullname;

            var tdPoints = document.createElement('td');
            tdPoints.className = 'airpay-lb__points text-end';
            tdPoints.textContent = r.points;

            tr.appendChild(tdRank);
            tr.appendChild(tdUser);
            tr.appendChild(tdPoints);
            tbody.appendChild(tr);
        });

        // Update "your rank" line.
        var myRankNode = root.querySelector('[data-my-rank]');
        if (myRankNode && response.my_rank > 0) {
            Str.get_string('your_rank',
                'local_sentientia_leaderboard',
                response.my_rank).then(function(s) {
                if (myRankNode.firstChild) {
                    myRankNode.firstChild.textContent = s;
                } else {
                    myRankNode.textContent = s;
                }
            });
        }

        // Update last_recomputed caption.
        var updated = root.querySelector('[data-last-recomputed]');
        if (updated && response.last_recomputed) {
            var d = new Date(response.last_recomputed * 1000);
            updated.textContent = '↻ ' + d.toLocaleString();
        }
    }

    function startPolling(boardid, root) {
        return window.setInterval(function() {
            fetchBoard(boardid).then(function(resp) {
                renderRows(root, resp);
            }).catch(function(err) {
                Notification.exception(err);
            });
        }, POLL_INTERVAL_MS);
    }

    function startSSE(boardid, root) {
        var wwwroot = (typeof M !== 'undefined' && M.cfg && M.cfg.wwwroot)
            ? M.cfg.wwwroot : '';
        var streamUrl = wwwroot
            + '/local/sentientia_leaderboard/stream.php?boardid='
            + encodeURIComponent(boardid);

        var es;
        try {
            es = new EventSource(streamUrl, {withCredentials: false});
        } catch (e) {
            return null;
        }

        es.addEventListener('sync', function() {
            // No-op. Server initial render is canonical.
        });

        es.addEventListener('leaderboard.recomputed', function() {
            fetchBoard(boardid).then(function(resp) {
                renderRows(root, resp);
            }).catch(function() {
                // Silent — next event or poll-tick retries.
            });
        });

        es.addEventListener('reconnect', function() {
            // No-op — EventSource handles auto-reconnect.
        });

        es.addEventListener('error', function() {
            if (es.readyState === EventSource.CLOSED) {
                window.setTimeout(function() {
                    startPolling(boardid, root);
                }, SSE_RECONNECT_DELAY_MS);
            }
        });

        return es;
    }

    function init(opts) {
        opts = opts || {};
        var boardid = opts.boardid;
        var realtime = opts.realtime !== false;

        if (!boardid) {
            return;
        }

        var root = document.querySelector(
            '.airpay-lb[data-boardid="' + boardid + '"]');
        if (!root) {
            return;
        }

        if (realtime && typeof window.EventSource !== 'undefined') {
            var onIndicator = root.querySelector('[data-live-on]');
            var offIndicator = root.querySelector('[data-live-off]');
            if (onIndicator) {
                onIndicator.style.display = '';
            }
            if (offIndicator) {
                offIndicator.style.display = 'none';
            }
            startSSE(boardid, root);
        } else {
            startPolling(boardid, root);
        }
    }

    return {
        init: init
    };
});
